parameters.jsCode:
$getWorkflowStaticData('global').phase = "evaluation"

const agentDescription = $input.first().json['agent description'];

const skills = $input.first().json.skills;

// Convert skills object into readable formatted JSON
const formattedSkills = JSON.stringify(skills, null, 2);

const chatInput = `
You are an expert AI system prompt engineer.

Your task is to create a concise, production-grade system prompt for a custom AI agent.

USER AGENT DESCRIPTION:
${agentDescription}

AVAILABLE SKILLS:
${formattedSkills}

INSTRUCTIONS:

1. Analyze the requested agent behavior carefully.

2. Select ONLY the skills that are directly useful.

3. Integrate selected skills naturally into the generated system prompt.

4. Ignore irrelevant skills completely.

5. The generated system prompt must:
- contain exactly 5 concise sentences
- define the agent role clearly
- define behavior and reasoning style
- define communication style
- define skill usage policy
- minimize hallucinations
- avoid unnecessary verbosity

6. Do NOT use markdown.

7. Do NOT explain your reasoning.

8. Output ONLY the final system prompt text.

9. The final result will be used directly as a production system prompt for another AI agent.

IMPORTANT:
Be precise, compact, deterministic, and operationally clear.
`;

return [
  {
    json: {
      chatInput,
      sessionId: $execution.id
    }
  }
];

